#rooms{grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.thermostat{--ring:#69d8c3;--ring-rgb:105,216,195;min-width:0;padding:12px;border:1px solid #344854;border-radius:20px;background:radial-gradient(circle at 50% 32%,rgba(var(--ring-rgb),.09),transparent 45%),linear-gradient(145deg,#1e2e39,#132029 75%);box-shadow:0 16px 35px #0005}.thermostat[data-demand="true"]{--ring:#ff705c;--ring-rgb:255,112,92;border-color:#ff705c80}.thermostat[data-powered="false"]{--ring:#71808a;--ring-rgb:113,128,138;opacity:.82}.thermostat .header,.thermostat .tile-footer,.thermostat .setpoint-controls{display:flex;align-items:center}.thermostat .header{justify-content:space-between;gap:5px}.thermostat h3{margin:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.88rem}.thermostat .status{display:inline-flex;align-items:center;gap:5px;color:#9dafbb;font-size:.58rem;font-weight:700;white-space:nowrap}.thermostat .status::before{width:7px;height:7px;border-radius:50%;background:var(--ring);box-shadow:0 0 10px var(--ring);content:""}.thermostat .dial{position:relative;display:grid;width:min(100%,124px);aspect-ratio:1;margin:13px auto;place-items:center;border-radius:50%;background:radial-gradient(circle,transparent 65%,#091118 66% 72%,transparent 73%),conic-gradient(from 220deg,var(--ring) 0 72%,#344550 72% 86%,transparent 86%);filter:drop-shadow(0 11px 18px #0007)}.thermostat .dial::before{position:absolute;inset:9px;border:1px solid #9cb5c43b;border-radius:50%;background:radial-gradient(circle at 42% 30%,#2b3b46,#17242d 55%,#101a21);box-shadow:inset 0 0 28px #0007,0 0 20px rgba(var(--ring-rgb),.14);content:""}.thermostat .dial-content{position:relative;z-index:1;display:grid;place-items:center;text-align:center}.thermostat .label{color:#9dafbb;font-size:.58rem;font-weight:750;letter-spacing:.1em;text-transform:uppercase}.thermostat .current{margin:2px 0;font-size:1.95rem;font-weight:500;line-height:1;letter-spacing:-.05em;font-variant-numeric:tabular-nums}.thermostat .current small{margin-left:2px;color:#9dafbb;font-size:.65rem;font-weight:700}.thermostat .heat-state{display:flex;align-items:center;gap:3px;min-height:16px;color:var(--ring);font-size:.58rem;font-weight:750}.thermostat .flame{width:11px;fill:currentColor}.thermostat .setpoint{margin:0;padding:9px 6px 7px;border:1px solid #536c7a80;border-radius:15px;background:#070d124d;text-align:center}.thermostat .setpoint-controls{justify-content:space-between;gap:4px}.thermostat .setpoint-value{display:grid;min-width:0;place-items:center}.thermostat .setpoint-value output{font-size:1.04rem;font-weight:780;font-variant-numeric:tabular-nums;white-space:nowrap}.thermostat .step,.thermostat .power,.thermostat .mode{border:1px solid #405461;color:#f4f7f9;cursor:pointer;transition:.15s ease}.thermostat .step{display:grid;width:36px;height:36px;flex:0 0 36px;place-items:center;padding:0;border-radius:50%;background:#293944;font-size:1.4rem;line-height:1}.thermostat .step:hover,.thermostat .step:focus-visible{border-color:var(--ring);background:rgba(var(--ring-rgb),.14);color:var(--ring)}.thermostat .pending{min-height:14px;margin:5px 0 -2px;color:#9dafbb;font-size:.59rem}.thermostat .pending[data-visible="true"]::before{display:inline-block;width:7px;height:7px;margin-right:6px;border:1px solid currentColor;border-right-color:transparent;border-radius:50%;content:"";animation:spin .7s linear infinite}.thermostat .tile-footer{justify-content:space-between;gap:7px;margin-top:10px}.thermostat .power{display:grid;width:36px;height:36px;flex:0 0 36px;place-items:center;padding:0;border-radius:12px;background:#273640;color:#82929c}.thermostat .power svg{width:19px;fill:none;stroke:currentColor;stroke-linecap:round;stroke-width:1.9}.thermostat .power[aria-pressed="true"]{border-color:rgba(var(--ring-rgb),.55);background:rgba(var(--ring-rgb),.12);color:var(--ring)}.thermostat .mode{min-height:36px;flex:1;padding:4px;border-color:#69d8c36b;border-radius:12px;background:#69d8c31a;color:#6